impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut prefix = vec![0i128; n + 1];
        for i in 0..n {
            prefix[i + 1] = prefix[i] + nums[i] as i128;
        }

        let mut dp_prev = vec![0i128; n + 1];
        let mut dp_cur = vec![0i128; n + 1];

        for _ in 1..=k {
            // dp_cur[0] stays 0
            for i in 1..=n {
                let mut best = dp_cur[i - 1];
                if i >= m {
                    let candidate = dp_prev[i - m] + (prefix[i] - prefix[i - m]);
                    if candidate > best {
                        best = candidate;
                    }
                }
                dp_cur[i] = best;
            }
            dp_prev.clone_from_slice(&dp_cur);
        }

        dp_prev[n]
    }
}

